import json, math
from pathlib import Path
P=Path('predictions.json')
def save(n, series):
 d=json.loads(P.read_text());d[f'fig_{n:02}.png']=series;P.write_text(json.dumps(d,ensure_ascii=False,indent=2))
def s(name, pts):return {'name':name,'data':[{'x':round(x,7),'y':round(y,7)} for x,y in pts]}
def pix(name,pts,x0,x1,v0,v1,y0,y1,w0,w1,lx=False,ly=False):
 def cv(p,a,b,c,d,l):
  t=(p-a)/(b-a)
  return 10**(math.log10(c)+t*(math.log10(d)-math.log10(c))) if l else c+t*(d-c)
 return s(name,[(cv(x,x0,x1,v0,v1,lx),cv(y,y0,y1,w0,w1,ly)) for x,y in pts])
